% =========================================================================
% Fig. 3: Achieved vs. target kurtosis of the adaptive constellation
%
% Evaluates the kurtosis kappa_n = E{|x_n|^4} of the constellations
% generated by the pretrained adaptive constellation family (polar
% parameterization) for target kurtosis values between 1 and 2.
% The inset zooms into the region close to unit-modulus constellations.
%
% Reference:
% [1] B. Geiger, L. Hampel, and L. Schmalen, "Joint power and
%     adaptive-constellation optimization for OFDM-ISAC systems," in Proc.
%     IEEE Conf. Integr. Sens. Commun. (ISAC), Lisbon, Portugal, Nov. 2026.
%     arXiv:2611.12166
%
% License: MIT (see LICENSE in repository root)
% =========================================================================

clear; close all;

kappa_target = 1:0.01:2;                    % target kurtosis values
kappa_target_fine = 1:0.001:1.034;          % fine grid for the inset
matlab_dir = fileparts(fileparts(mfilename("fullpath")));   % .../matlab
addpath(matlab_dir, fullfile(matlab_dir, "functions"));
weights = load(fullfile(matlab_dir, "adaptive_constellation_weights.mat"));

kappa_achieved = achieved_kurtosis(kappa_target, weights);
kappa_achieved_fine = achieved_kurtosis(kappa_target_fine, weights);

fprintf("Max. deviation |kappa - kappa_target| = %.2e\n", ...
        max(abs(kappa_achieved - kappa_target)));

%% Plot
figure("Name", "Fig. 3: Achieved kurtosis");
plot(kappa_target, kappa_target, "k:", "LineWidth", 1); hold on;
plot(kappa_target, kappa_achieved, "LineWidth", 1.5);
grid on; box on; axis([1 2 1 2]);
xlabel("Target kurtosis $\tilde{\kappa}_n$", "Interpreter", "latex");
ylabel("Achieved kurtosis $\kappa_n$", "Interpreter", "latex");
legend(["Ideal", "Adaptive polar"], "Location", "southeast");

% Inset close to kappa = 1
axes("Position", [0.2 0.55 0.3 0.3]);
plot(kappa_target_fine, kappa_target_fine, "k:", "LineWidth", 1); hold on;
plot(kappa_target_fine, kappa_achieved_fine, "LineWidth", 1.5);
grid on; box on; axis([1 1.03 1 1.03]);


function kappa = achieved_kurtosis(kappa_target, weights)
kappa = zeros(size(kappa_target));
for k = 1:numel(kappa_target)
    [x, p] = generate_adaptive_constellation(kappa_target(k), weights);
    kappa(k) = sum(p .* abs(x).^4);
end
end
